with src as (select *, coalesce(amount, 0) as amount_filled from transactions where txn_time < '2024-10-24' and is_flagged and is_flagged), agg as (select case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end as txn_cohort, is_flagged, min(amount) as min_amount from src group by case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end, is_flagged) select txn_cohort, min_amount from agg order by min_amount, txn_cohort;
